function adLoad(p) {
  var me = pin_(p);
  noteLastUsed_(me);
  adminLog_('Admin login');

  CURRENT_USER_ = who;
  noteLastUsed_({ name: who, owner: who === 'Owner' });
} else {

/* ---------- Staff access from the admin portal (owner only) and Change my PIN (any admin) ---------- */
function weakPin_(pin) {
  if (!/^\d{6,12}$/.test(pin)) return 'The number must be 6 to 12 digits.';
  if (/^(\d)\1+$/.test(pin)) return 'Do not use the same digit repeated.';
  var up = '01234567890123', dn = '98765432109876';
  if (up.indexOf(pin) >= 0 || dn.indexOf(pin) >= 0) return 'Do not use digits in order, like 123456.';
  if (/^(19|20)\d{2}(0[1-9]|1[0-2])(0[1-9]|[12]\d|3[01])$/.test(pin) || /^(0[1-9]|[12]\d|3[01])(0[1-9]|1[0-2])(19|20)\d{2}$/.test(pin)) return 'Do not use a date.';
  return '';
}
function ownerOnly_(p) {
  var u = pin_(p);
  if (!u.owner) throw new Error('Only the owner can manage staff access.');
  return u;
}
function staffMail_(subject, body) {
  try { MailApp.sendEmail(Session.getEffectiveUser().getEmail(), 'SSFFA Training: ' + subject, body + '\n\nIf you did not do this, change the owner PIN from the sheet menu (SSFFA > Change admin PIN) and check the Admin log tab.'); } catch (e) {}
}
function cancelTokens_(name) {
  var sp = PropertiesService.getScriptProperties(), all = sp.getProperties();
  Object.keys(all).forEach(function (k) { if (/^VT_/.test(k) && all[k].split('|')[0] === name) sp.deleteProperty(k); });
}
function adStaffList(p) {
  ownerOnly_(p);
  var u = users_(), sp = PropertiesService.getScriptProperties();
  var list = Object.keys(u).map(function (k) { return { id: k, name: u[k].name, role: u[k].role, added: u[k].added || '', last: u[k].last || '' }; });
  list.sort(function (a, b) { return a.role === b.role ? a.name.localeCompare(b.name) : (a.role === 'admin' ? -1 : 1); });
  return { owner: { last: sp.getProperty('OWNER_LAST') || '' }, list: list };
}
/** f = { id (empty for a new person), name, role 'admin' or 'view', pin (required for a new person, optional when changing) } */
function adStaffSave(p, f) {
  ownerOnly_(p);
  f = f || {};
  var u = users_(), role = f.role === 'view' ? 'view' : 'admin', pin = String(f.pin || '').trim(), isNew = !f.id;
  var name = String(f.name || '').replace(/\s+/g, ' ').trim().slice(0, 60);
  if (isNew) {
    if (!name) throw new Error('Type the person\'s name or role.');
    var id = name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
    if (!id || id === 'owner') throw new Error('Choose a different name.');
    if (u[id]) throw new Error(name + ' already has access. Use Change on their row instead.');
    if (!pin) throw new Error('Set a number for ' + name + '.');
    f.id = id;
  } else if (!u[f.id]) throw new Error('That person was not found. Refresh the list.');
  if (pin) {
    var weak = weakPin_(pin); if (weak) throw new Error(weak);
    var w = whoIs_(pin);
    if (w && !(u[f.id] && u[f.id].hash === hash_(pin))) throw new Error('That number is already used by someone else. Choose a different one.');
  }
  var rec = u[f.id] || { name: name, added: Utilities.formatDate(new Date(), 'Africa/Juba', 'yyyy-MM-dd') };
  rec.role = role;
  if (pin) rec.hash = hash_(pin);
  u[f.id] = rec; saveUsers_(u);
  if (isNew) {
    adminLog_('Access ' + role.toUpperCase() + ' added for ' + rec.name + ' (from the admin portal)');
    staffMail_(rec.name + ' was added', rec.name + ' was given ' + (role === 'admin' ? 'ADMIN access (admin portal and dashboard)' : 'VIEW access (dashboard only)') + ' from the admin portal on ' + Utilities.formatDate(new Date(), 'Africa/Juba', 'd MMM yyyy, HH:mm') + ' (Juba time).');
  } else {
    if (pin) cancelTokens_(rec.name);
    adminLog_('Access for ' + rec.name + ' changed to ' + role.toUpperCase() + (pin ? ', new PIN set' : '') + ' (from the admin portal)');
  }
  return adStaffList(p);
}
function adStaffRemove(p, id) {
  ownerOnly_(p);
  var u = users_();
  if (!u[id]) throw new Error('That person was not found. Refresh the list.');
  var nm = u[id].name; delete u[id]; saveUsers_(u); cancelTokens_(nm);
  adminLog_('Access removed for ' + nm + ' (from the admin portal)');
  staffMail_(nm + ' was removed', nm + ' no longer has access to the admin portal or the dashboard.');
  return adStaffList(p);
}
/** Any signed-in admin changes their own PIN. cur must be their current PIN. */
function adMyPin(p, cur, next) {
  var me = pin_(p), who = whoIs_(String(cur || '').trim());
  if (!who || who.name !== me.name) throw new Error('Your current number is not right. Nothing was changed.');
  next = String(next || '').trim();
  var weak = weakPin_(next); if (weak) throw new Error(weak);
  var w = whoIs_(next);
  if (w && w.name !== me.name) throw new Error('That number is already used by someone else. Choose a different one.');
  var sp = PropertiesService.getScriptProperties();
  if (me.owner) {
    sp.setProperty('ADMIN_PIN', next);
    staffMail_('Owner PIN changed', 'The owner PIN was changed from the admin portal on ' + Utilities.formatDate(new Date(), 'Africa/Juba', 'd MMM yyyy, HH:mm') + ' (Juba time).');
  } else {
    var u = users_(), k = Object.keys(u).filter(function (x) { return u[x].name === me.name; })[0];
    if (!k) throw new Error('Your access was not found. Ask the owner.');
    u[k].hash = hash_(next); saveUsers_(u);
  }
  adminLog_('Changed their own PIN');
  return { ok: true };
}
/** Records the day each person last signed in (at most one write per person per day). */
function noteLastUsed_(u) {
  try {
    var d = Utilities.formatDate(new Date(), 'Africa/Juba', 'yyyy-MM-dd'), sp = PropertiesService.getScriptProperties();
    if (u.owner) { if (sp.getProperty('OWNER_LAST') !== d) sp.setProperty('OWNER_LAST', d); return; }
    var all = users_();
    for (var k in all) if (all[k].name === u.name && all[k].last !== d) { all[k].last = d; saveUsers_(all); return; }
  } catch (e) {}
}

/* ---------- Dashboard behind a PIN, remembered on the device for 90 days ---------- */

