var ADMIN_HTML_ = "<!DOCTYPE html>
<html><head><base target="_top"><meta charset="utf-8">
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Barlow:wght@400;500;600&family=Barlow+Condensed:wght@600;700&display=swap">
<style>
:root{--bg:#F3F5FB;--surface:#fff;--ink:#141C45;--muted:#586088;--line:#DCE1F0;--blue:#27449C;--soft:#E6EBFA;--red:#ED1C24;--ok:#16794C;--okbg:#DDF3E8;--wait:#8A4B00;--waitbg:#FDEBD3;--err:#B3261E;--errbg:#FBE3E1;--display:'Barlow Condensed','Arial Narrow',Arial,sans-serif;--body:'Barlow',Arial,sans-serif}
*{box-sizing:border-box}[hidden]{display:none!important}
body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--body);font-size:15px;line-height:1.5}
.mast{background:var(--blue);color:#fff;border-bottom:5px solid var(--red)}
.mast .in{max-width:1100px;margin:0 auto;padding:14px 16px;display:flex;align-items:center;gap:14px}
.mast img{width:56px;height:56px;background:#fff;border-radius:50%;padding:2px}
.mast h1{font-family:var(--display);text-transform:uppercase;font-size:26px;margin:0;line-height:1}
