.mast .out{margin-left:auto}
nav{background:var(--surface);border-bottom:1px solid var(--line);position:sticky;top:0;z-index:5}
nav .in{max-width:1100px;margin:0 auto;padding:0 16px;display:flex;gap:2px;overflow-x:auto}
nav button{background:none;border:0;border-bottom:4px solid transparent;font-family:var(--display);font-weight:600;font-size:16px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);padding:13px 12px 9px;cursor:pointer;white-space:nowrap}
nav button[aria-selected="true"]{color:var(--blue);border-bottom-color:var(--blue)}
main{max-width:1100px;margin:0 auto;padding:18px 16px 50px}
.card{background:var(--surface);border:1px solid var(--line);border-radius:8px;padding:18px;margin-bottom:18px;min-width:0}
h2{font-family:var(--display);text-transform:uppercase;font-size:21px;letter-spacing:.04em;color:var(--blue);margin:0}
.sub{color:var(--muted);font-size:13.5px;margin:2px 0 14px}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}
