label{font-size:12px;font-weight:600;letter-spacing:.07em;text-transform:uppercase;color:var(--muted)}
input,select,textarea{font:inherit;padding:9px 10px;border:1.5px solid var(--line);border-radius:6px;background:#fff;color:var(--ink);width:100%}
