.row{display:flex;flex-wrap:wrap;gap:10px;align-items:end}
.scroll{overflow-x:auto}
table{width:100%;border-collapse:collapse;font-size:14px}
th{text-align:left;font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);padding:8px;border-bottom:2px solid var(--line);white-space:nowrap}
td{padding:7px 8px;border-bottom:1px solid var(--line);vertical-align:middle}
td select{padding:6px 8px}
tr.click{cursor:pointer}tr.click:hover td{background:var(--soft)}
.pill{display:inline-block;padding:2px 9px;border-radius:99px;font-size:12px;font-weight:600}
.pill.ok{background:var(--okbg);color:var(--ok)}.pill.wait{background:var(--waitbg);color:var(--wait)}.pill.info{background:var(--soft);color:var(--blue)}.pill.bad{background:#FBE3E1;color:#B3261E}
