.trchips{margin-top:6px;display:flex;flex-wrap:wrap;gap:6px;align-items:center}.chip{font:inherit;font-size:12px;padding:3px 10px;border-radius:999px;border:1px solid #DCE1F0;background:#F3F5FB;color:#27449C;cursor:pointer}.chip:hover{background:#E6EBFA}

