.sx-ch small{display:block;color:var(--muted);font-size:12.5px;line-height:1.35}
.sx-pinrow{display:flex;gap:8px}.sx-pinrow input{letter-spacing:.25em;font-size:18px;font-weight:600}.sx-pinrow .sx-ib{flex:none}
