<div class="mast"><div class="in"><img src="<?!= logo ?>" alt="SSFFA logo"><div><h1>Training Admin</h1><p>SSFFA Training Management System</p></div><div class="sx-top" id="sxTop" hidden><span class="sx-who">Signed in as<b id="meName"></b></span><button class="btn ghost" id="myPinB" type="button">My PIN</button><button class="btn ghost" id="lock" hidden>Lock</button></div></div></div>

