      <div class="f"><label for="pCert">Certificate</label><select id="pCert"><option>Yes</option><option>No</option><option>Pending</option></select></div>
      <div class="f" style="justify-content:end"><button class="btn ghost" id="pAdd" type="button">Add to list</button></div>
    </div>
    <div class="scroll" style="margin-top:14px"><table><thead><tr><th>#</th><th>Name</th><th>Gender</th><th>Station</th><th>Company</th><th>Cert</th><th></th></tr></thead><tbody id="pList"><tr><td colspan="7" class="muted">No attendees added yet.</td></tr></tbody></table></div>
    <div class="row" style="margin-top:14px;justify-content:space-between"><span class="muted" id="pCount"></span><button class="btn" id="aSave" type="button">Save attendance</button></div>
  </div>
</section>
<!-- CERTIFICATES -->
<section id="v-cert" hidden>
