<script>
var $=function(i){return document.getElementById(i);},PIN='',D=null,LIST=[],CROWS=[],KROW=null;
var esc=function(s){return String(s==null?'':s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});};
var MON=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
function fd(s){if(!s)return '';var p=s.split('-');return (+p[2])+' '+MON[+p[1]-1]+' '+p[0];}
function toast(t,bad){var d=document.createElement('div');d.className='toast'+(bad?' err':'');d.textContent=t;document.body.appendChild(d);setTimeout(function(){d.remove();},3200);}
function call(fn,args,ok){var r=google.script.run.withSuccessHandler(ok).withFailureHandler(function(e){toast(niceErr(e),true);busy(false);if(/PIN/.test(e.message))lock();});r[fn].apply(r,[PIN].concat(args));}
function busy(b){document.querySelectorAll('.btn').forEach(function(x){if(x.id!=='lock')x.disabled=b;});}
function up(s){return String(s||'').toUpperCase().replace(/\s+/g,' ').trim();}
function lock(){PIN='';$('app').hidden=true;$('gate').hidden=false;$('lock').hidden=true;$('sxTop').hidden=true;$('tabStaff').hidden=true;$('sxDim').hidden=true;$('pin').value='';}
$('lock').onclick=lock;
$('pinF').onsubmit=function(e){e.preventDefault();PIN=$('pin').value.trim()+'|'+ssffaDev();$('pinB').disabled=true;$('pinB').textContent='Checking...';
  google.script.run.withSuccessHandler(function(d){$('pinB').disabled=false;$('pinB').textContent='Unlock';D=d;$('gate').hidden=true;$('app').hidden=false;$('lock').hidden=false;meSet();view('ses');init();})
  .withFailureHandler(function(e){$('pinB').disabled=false;$('pinB').textContent='Unlock';toast(e.message,true);PIN='';}).adLoad(PIN);};
function reload(cb){call('adLoad',[],function(d){D=d;init(true);if(cb)cb();});}
function opts(el,vals,first){el.innerHTML=(first?'<option value="">'+first+'</option>':'')+vals.map(function(v){return '<option>'+esc(v)+'</option>';}).join('');}
function uniq(a){var s={};a.forEach(function(x){if(x)s[x]=1;});return Object.keys(s).sort();}
function trChips(){var seen={},a=[];(D&&D.sess||[]).forEach(function(x){String(x.trainers||'').split(',').forEach(function(n){n=n.trim();var k=n.toLowerCase();if(n&&!seen[k]){seen[k]=1;a.push(n);}});});var el=$('nTrChips');if(!el)return;el.innerHTML=a.length?'<span class="muted" style="font-size:12px">Recent:</span> '+a.slice(0,12).map(function(n){return '<button type="button" class="chip">'+esc(n)+'</button>';}).join(''):'';el.querySelectorAll('.chip').forEach(function(b){b.onclick=function(){var i=$('nTrainers'),cur=i.value.split(',').map(function(x){return x.trim();}).filter(String);if(cur.map(function(x){return x.toLowerCase();}).indexOf(b.textContent.toLowerCase())<0)cur.push(b.textContent);i.value=cur.join(', ');};});}
function init(keep){try{trChips();}catch(e){}
  ['pStation','kStation'].forEach(function(i){var v=$(i).value;opts($(i),D.stations,'Choose');$(i).value=v;});
  $('agents').innerHTML=D.agents.map(function(a){return '<option value="'+esc(a.name)+'">';}).join('');
  $('companies').innerHTML=uniq(D.agents.map(function(a){return up(a.company);}).concat(D.ccfl.map(function(c){return up(c.host);}))).map(function(c){return '<option value="'+esc(c)+'">';}).join('');
  $('topics').innerHTML=uniq(D.sessions.map(function(s){return s.topic;})).map(function(c){return '<option value="'+esc(c)+'">';}).join('');
  $('partners').innerHTML=uniq(D.sessions.map(function(s){return s.partner;})).map(function(c){return '<option value="'+esc(c)+'">';}).join('');
  var so=D.sessions.map(function(s,i){return '<option value="'+i+'">'+esc(fd(s.start)+'  |  '+s.topic+'  |  '+s.partner+' ('+s.n+')')+'</option>';}).join('');
  var SL=sortSess();var a=$('aPick').value;$('aPick').innerHTML=sessOpts(SL,'Choose a session');$('aPick').value=keep&&a?a:'';$('aPick').onchange();
  var c=$('cPick').value;$('cPick').innerHTML=sessOpts(SL.filter(function(s){return s.n>0;}),'Choose a session');if(keep)$('cPick').value=c;
  renderK();renderSess();qFill();
}
/* tabs */
document.querySelectorAll('nav button').forEach(function(b){b.onclick=function(){document.querySelectorAll('nav button').forEach(function(x){x.setAttribute('aria-selected',x===b?'true':'false');});SX_VIEWS.forEach(function(v){var e=$('v-'+v);if(e)e.hidden=v!==b.dataset.v;});if(b.dataset.v==='staff'){sxClose();sxLoad();}};});
/* attendance */
function sortSess(){var rank={Open:0,Applications:1,Planned:2,Closed:3};return (D.sess||[]).slice().sort(function(a,b){return (rank[a.status]-rank[b.status])||b.start.localeCompare(a.start);});}
function sessOpts(list,first){return '<option value="">'+first+'</option>'+list.map(function(s){return '<option value="'+esc(s.id)+'">'+esc(fd(s.start)+'  |  '+s.topic+'  |  '+s.partner+'  ('+s.n+')'+(s.status==='Open'?'  OPEN':''))+'</option>';}).join('');}
function sessById(id){return (D.sess||[]).filter(function(x){return x.id===id;})[0];}
$('aPick').onchange=function(){var s=sessById($('aPick').value);$('aInfo').textContent=s?(s.id+'  |  '+s.type+'  |  '+(s.venue||'No venue')+'  |  '+s.n+' attendee(s) so far  |  Check-in '+s.status):'';};
$('pName').addEventListener('change',function(){var n=up(this.value);this.value=n;var a=D.agents.filter(function(x){return x.name===n;})[0];if(a){$('pGender').value=a.gender;$('pStation').value=a.station;$('pCompany').value=a.company;$('pPhone').value=a.phone.replace(/^'/,'');$('pEmail').value=a.email||'';toast('Returning agent: details filled in');}});
function renderP(){$('pList').innerHTML=LIST.length?LIST.map(function(p,i){return '<tr><td>'+(i+1)+'</td><td>'+esc(p.name)+'</td><td>'+esc(p.gender)+'</td><td>'+esc(p.station)+'</td><td>'+esc(up(p.company))+'</td><td>'+esc(p.cert)+'</td><td><button class="btn ghost" style="padding:3px 10px" data-i="'+i+'">Remove</button></td></tr>';}).join(''):'<tr><td colspan="7" class="muted">No attendees added yet.</td></tr>';$('pCount').textContent=LIST.length?LIST.length+' ready to save':'';}
$('pList').onclick=function(e){var b=e.target.closest('button[data-i]');if(b){LIST.splice(+b.dataset.i,1);renderP();}};
$('pAdd').onclick=function(){var p={name:up($('pName').value),gender:$('pGender').value,station:$('pStation').value,company:$('pCompany').value,phone:$('pPhone').value,email:$('pEmail').value,cert:$('pCert').value};
  if(p.name.split(' ').length<2)return toast('Enter the full name',true);if(!p.gender||!p.station)return toast('Choose gender and station',true);
  if(LIST.some(function(x){return x.name===p.name;}))return toast('Already in the list',true);
  LIST.push(p);renderP();['pName','pCompany','pPhone','pEmail'].forEach(function(i){$(i).value='';});$('pGender').value='';$('pStation').value='';$('pName').focus();};
$('aSave').onclick=function(){var s=sessById($('aPick').value);if(!s)return toast('Choose a session first',true);if(!LIST.length)return toast('Add at least one attendee',true);
  busy(true);call('adAddAttendees',[s,LIST],function(r){busy(false);var dup=r.filter(function(x){return x.dup;}).length,bad=r.filter(function(x){return !x.ok;}).length;
  toast('Saved '+(r.length-dup-bad)+' attendee(s)'+(dup?', '+dup+' already registered':'')+(bad?', '+bad+' rejected':''));LIST=[];renderP();reload();});};
/* certificates */
$('cPick').onchange=function(){var s=sessById(this.value);if(!s){$('cList').innerHTML='';return;}call('adSessionRows',[s.start,s.topic],function(r){CROWS=r;$('cList').innerHTML=r.map(function(x,i){return '<tr><td>'+esc(x.name)+'</td><td>'+esc(x.station)+'</td><td><select data-i="'+i+'" style="width:auto">'+['Yes','No','Pending'].map(function(o){return '<option'+(o===x.cert?' selected':'')+'>'+o+'</option>';}).join('')+'</select></td><td style="white-space:nowrap">'+(x.cert==='Yes'?'<button class="btn ghost" style="padding:3px 10px" data-pdf="'+i+'">PDF</button> ':'')+'<button class="btn ghost" style="padding:3px 10px;color:#B3261E;border-color:#B3261E" data-del="'+i+'">Remove</button></td></tr>';}).join('')||'<tr><td colspan="4" class="muted">No attendees.</td></tr>';});};
$('cList').onchange=function(e){var s=e.target.closest('select[data-i]');if(s)CROWS[+s.dataset.i].cert=s.value;};
$('cAll').onclick=function(){CROWS.forEach(function(x){x.cert='Yes';});document.querySelectorAll('#cList select').forEach(function(s){s.value='Yes';});};
$('cSave').onclick=function(){if(!CROWS.length)return toast('Choose a session first',true);busy(true);call('adSaveCerts',[CROWS.map(function(x){return {row:x.row,cert:x.cert};})],function(n){busy(false);toast('Saved '+n+' certificate records');reload();});};
/* ccfl */
var KF={name:'kName',reg:'kReg',intake:'kIntake',gender:'kGender',station:'kStation',host:'kHost',loc:'kLoc',status:'kStatus',grad:'kGrad',cert:'kCert',phone:'kPhone',email:'kEmail',notes:'kNotes'};
function renderK(){var q=up($('kSearch').value);$('kList').innerHTML=D.ccfl.filter(function(c){return !q||up(c.name+' '+c.reg).indexOf(q)>-1;}).map(function(c){var cls=c.status==='Graduated'?'ok':/Awaiting|attachment/.test(c.status)?'wait':'info';return '<tr class="click" data-r="'+c.row+'"><td><input type="checkbox" data-r="'+c.row+'" style="width:auto" aria-label="Select '+esc(c.name)+'"></td><td>'+esc(c.name)+'</td><td>'+esc(c.reg)+'</td><td>'+esc(c.gender)+'</td><td><span class="pill '+cls+'">'+esc(c.status)+'</span></td><td>'+esc(c.cert)+'</td></tr>';}).join('');}
$('kSearch').oninput=renderK;
$('kList').onclick=function(e){if(e.target.type==='checkbox')return;var tr=e.target.closest('tr[data-r]');if(!tr)return;var c=D.ccfl.filter(function(x){return x.row===+tr.dataset.r;})[0];KROW=c.row;Object.keys(KF).forEach(function(k){$(KF[k]).value=(c[k]||'').replace(/^'/,'');});$('kTitle').textContent='Edit: '+c.name;window.scrollTo({top:0,behavior:'smooth'});};
$('kNew').onclick=function(){KROW=null;Object.keys(KF).forEach(function(k){$(KF[k]).value='';});$('kStatus').value='Enrolled';$('kTitle').textContent='Add CCFL student';$('kName').focus();};
$('kSave').onclick=function(){var x={row:KROW};Object.keys(KF).forEach(function(k){x[k]=$(KF[k]).value.trim();});x.name=up(x.name);if(!x.name||!x.reg)return toast('Full name and Reg. No. are required',true);
  busy(true);call('adSaveCcfl',[x],function(){busy(false);toast(KROW?'Student updated':'Student added');reload(function(){$('kNew').click();});});};
$('kAllChk').onchange=function(){var v=this.checked;document.querySelectorAll('#kList input[type=checkbox]').forEach(function(c){c.checked=v;});};
$('kBulkGo').onclick=function(){var st=$('kBulk').value,rows=[].map.call(document.querySelectorAll('#kList input:checked'),function(c){return +c.dataset.r;});if(!st||!rows.length)return toast('Select students and a status',true);
  busy(true);var left=rows.length;rows.forEach(function(r){var c=D.ccfl.filter(function(x){return x.row===r;})[0];var x=JSON.parse(JSON.stringify(c));x.status=st;call('adSaveCcfl',[x],function(){if(--left===0){busy(false);toast('Updated '+rows.length+' students');$('kAllChk').checked=false;reload();}});});};
/* sessions */
function renderSess(){var show=$('sShow').value,all=sortSess(),list=all.filter(function(s){return show==='all'||s.status!=='Closed';});
  $('sCount').textContent=list.length+' of '+all.length+' sessions';
  $('sList').innerHTML=list.length?list.map(function(s){var cls=s.status==='Open'?'ok':s.status==='Applications'?'wait':s.status==='Planned'?'info':'';var act=sessActs(s);
    return '<tr><td class="muted">'+esc(s.id)+'</td><td style="white-space:nowrap">'+fd(s.start)+(s.end&&s.end!==s.start?' to '+fd(s.end):'')+'</td><td><b>'+esc(s.topic)+'</b>'+(s.trainers?'<div class="muted" style="font-size:12px">Trainer: '+esc(s.trainers)+'</div>':'')+(s.status==='Applications'||s.apps?'<div class="muted" style="font-size:12px">'+(s.apps||0)+' applied'+(s.short?', '+s.short+' shortlisted':'')+(s.seats?' | '+s.seats+' seats':'')+(s.applyBy?' | apply by '+fd(s.applyBy):'')+'</div>':'')+'</td><td>'+esc(s.partner)+'</td><td>'+esc(s.venue)+'</td><td style="text-align:center">'+s.n+'</td><td><span class="pill '+cls+'"'+(cls?'':' style="background:#F1F2F6;color:#8A93B5"')+'>'+esc(s.status)+'</span>'+(s.status==='Open'&&s.code?'<div style="margin-top:4px;font-weight:700;letter-spacing:.12em;white-space:nowrap" title="Agents type this code to check in">Code '+esc(s.code)+'</div>':'')+'</td><td>'+act+' <button class="btn ghost" style="padding:4px 10px" data-edit="'+esc(s.id)+'">Edit</button></td></tr>';}).join(''):'<tr><td colspan="8" class="muted">No open or planned sessions. Create one above.</td></tr>';
  var open=all.filter(function(s){return s.status==='Open';});
  $('chkStatus').className='status '+(open.length?'open':'closed');
  $('chkStatus').textContent=open.length?'Open now ('+open.length+'): '+open.map(function(s){return s.topic+', '+fd(s.start)+(s.code?' (code '+s.code+')':'');}).join('  |  '):'No session is open for check-in';
  shFill();}
$('sShow').onchange=renderSess;
$('sList').onclick=function(e){var ed=e.target.closest('button[data-edit]');if(ed)return editSess(ed.dataset.edit);var b=e.target.closest('button[data-id]');if(!b)return;busy(true);call('adSetSession',[b.dataset.id,b.dataset.act],function(st){busy(false);toast({Open:'Check-in is open',Closed:'Check-in closed',Applications:'Applications are open',Planned:'Applications stopped'}[st]||'Saved');reload();});};
